import {searchMatches,compactStat} from './tatari-model.mjs';
import {resolveBuild,advantage,dojoBadgeIds} from './tatari-stats-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./tatari-data/',import.meta.url),name=x=>typeof x==='string'?x:x?.en||x?.zh||'';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const img=(src,alt,cls)=>{const n=el('img',undefined,cls);n.src=new URL(src,root);n.alt=alt;return n;};
let data,mode='calculator';const builds=[{pet:11,tier:1,stars:1,food:1,badgeMode:'none',badges:[]},{pet:22,tier:1,stars:1,food:1,badgeMode:'none',badges:[]}];
function field(title,node){const label=el('div',undefined,'build-field');label.append(el('span',title),node);return label;}
function select(options,value,label){const n=el('select');n.setAttribute('aria-label',label);for(const [v,t,disabled] of options){const o=new Option(t,v);o.disabled=!!disabled;n.append(o);}n.value=value;return n;}
function starPicker(build,index){const wrap=el('div',undefined,'star-control'),button=el('button',undefined,'star-choice');button.type='button';button.setAttribute('aria-label','Choose stars for Tatari '+(index+1));button.append(img('stars/'+String(build.stars).padStart(2,'0')+'.png',build.stars+' stars'),el('span','Star level '+build.stars));
 const dialog=el('dialog',undefined,'star-dialog'),title=el('h2','Choose star level'),close=el('button','Close','dialog-close');close.type='button';close.onclick=()=>dialog.close();const top=el('div',undefined,'dialog-heading');top.append(title,close);dialog.append(top,el('p','Choose the star image that matches your Tatari.'));
 const grid=el('div',undefined,'star-picker-grid');for(let n=1;n<=84;n++){const option=el('button');option.type='button';option.setAttribute('aria-label',n+' stars');option.setAttribute('aria-pressed',String(n===build.stars));const picture=img('stars/'+String(n).padStart(2,'0')+'.png',n+' stars');picture.loading='lazy';option.append(picture,el('span',String(n)));option.onclick=()=>{build.stars=n;dialog.close();render();};grid.append(option);}dialog.append(grid);button.onclick=()=>dialog.showModal();wrap.append(button,dialog);return wrap;}
function editor(index){const build=builds[index],unit=data.units.find(u=>u.id===build.pet),form=unit.forms.find(f=>f.evolution===build.tier),panel=el('section',undefined,'build-panel');panel.setAttribute('aria-label','Tatari '+(index+1)+' inputs');panel.append(el('h2',mode==='comparison'?'Tatari '+(index+1):'Your Tatari'));
 const search=el('input');search.type='search';search.placeholder='Name or alias…';search.setAttribute('aria-label','Search Tatari '+(index+1));
 const choose=select(data.units.map(u=>[u.id,name(u.forms[0].name)]),build.pet,'Select Tatari '+(index+1));search.oninput=()=>{const matches=data.units.filter(u=>searchMatches(u,search.value));choose.replaceChildren(...matches.map(u=>new Option(name(u.forms[0].name),u.id)));if(matches.some(u=>u.id===build.pet))choose.value=build.pet;else choose.selectedIndex=-1;};choose.onchange=()=>{build.pet=Number(choose.value);build.tier=1;build.badges=[];render();};panel.append(field('Tatari',search),choose);
 const tiers=el('div',undefined,'build-tiers');tiers.setAttribute('aria-label','Evolution tier for Tatari '+(index+1));for(const f of unit.forms){const b=el('button');b.type='button';b.setAttribute('aria-label',name(f.name)+' tier '+f.evolution);b.setAttribute('aria-pressed',String(f.evolution===build.tier));b.append(img(f.playerhead,name(f.name)),el('span','Tier '+f.evolution));b.onclick=()=>{build.tier=f.evolution;render();};tiers.append(b);}panel.append(tiers);
 const fields=el('div',undefined,'build-field-grid'),level=el('input');level.value=500;level.readOnly=true;level.setAttribute('aria-label','Tatari level 500 fixed');fields.append(field('Tatari level',level),field('Stars',starPicker(build,index)));
 const stages=unit.feedingStages.filter(r=>r.stage>=1&&r.stage<=11).sort((a,b)=>a.stage-b.stage),food=select(stages.map(r=>[r.stage,'Food stage '+r.stage]),build.food,'Food stage for Tatari '+(index+1));food.onchange=()=>{build.food=Number(food.value);render();};fields.append(field('Food level',food));
 panel.append(fields);
 const badgeBox=el('div',undefined,'dojo-badge-picker'),badgeRow=el('div',undefined,'dojo-badge-row'),matching=data.badges.filter(b=>b.element===unit.element).sort((a,b)=>a.id-b.id);const badgeHeader=el('div',undefined,'badge-heading');badgeHeader.append(el('span','Dojo badges'));const account=el('button','Use account settings');account.type='button';account.disabled=true;account.title='Available when login and saved dojo settings are added';badgeHeader.append(account);badgeBox.append(badgeHeader,el('p','Click your highest badge; click it again to clear.','badge-help'));for(const [i,badge] of matching.entries()){const button=el('button');button.type='button';button.setAttribute('aria-label','Dojo badge '+String.fromCharCode(65+i)+' for Tatari '+(index+1));button.setAttribute('aria-pressed',String(build.badgeMode==='pick'&&build.badges.includes(badge.id)));button.title=badge.name;button.append(img(badge.image,badge.name),el('span',String.fromCharCode(65+i)));button.onclick=()=>{const latest=build.badgeMode==='pick'?Math.max(-1,...matching.map((b,n)=>build.badges.includes(b.id)?n:-1)):-1;if(latest===i){build.badgeMode='none';build.badges=[];}else{build.badgeMode='pick';build.badges=dojoBadgeIds(data,unit.element,i);}render();};badgeRow.append(button);}badgeBox.append(badgeRow);panel.append(badgeBox);
 panel.append(el('p',name(form.name)+' · Tier '+build.tier,'selected-build'));return panel;}
function statArtwork(result,stat){const art=el('div',undefined,'result-art');art.append(img('food-stats/'+result.grades[stat]+stat.toLowerCase()+'.png',result.grades[stat]+' '+stat+' food grade'),el('strong',compactStat(result.values[stat])));art.title=stat+' '+Math.floor(result.values[stat]).toLocaleString('en');return art;}
function heading(result){const box=el('div',undefined,'result-pet');box.append(img(result.form.portrait,name(result.form.name)),el('h2',name(result.form.name)),el('span','Tier '+result.form.evolution));return box;}
function output(){try{const left=resolveBuild(data,builds[0]),right=mode==='comparison'?resolveBuild(data,builds[1]):null,body=el('section',undefined,'result-panel');body.append(el('h2',mode==='comparison'?'Head-to-head stats':'Estimated stats','result-title'));const battle=$('battle-mode').selectedOptions[0].textContent;body.append(el('p',battle,'result-battle'));
 if(!right){body.append(heading(left));const stats=el('div',undefined,'single-stats');for(const a of ['ATK','HP','DEF']){const item=el('div');item.append(statArtwork(left,a),el('span',a));stats.append(item);}body.append(stats);}else{const grid=el('div',undefined,'comparison-grid');grid.append(el('span'),heading(left),heading(right));for(const a of ['ATK','HP','DEF']){grid.append(el('strong',a,'compare-stat-label'));const higher=advantage(left.values[a],right.values[a]);for(const [side,r] of [['left',left],['right',right]]){const item=el('div',undefined,'compare-value'+(side===higher?' stat-higher':''));item.append(statArtwork(r,a));if(side===higher)item.append(el('span','Higher','higher-label'));grid.append(item);}}body.append(grid);}
 $('stats-output').replaceChildren(body);$('tool-status').textContent='';}catch(error){$('tool-status').textContent=error.message;}}
function render(){$('stats-workspace').classList.toggle('comparison-mode',mode==='comparison');$('build-editors').replaceChildren(...(mode==='comparison'?[editor(0),editor(1)]:[editor(0)]));output();}
function changeMode(next){mode=next;for(const m of ['calculator','comparison']){$(m+'-mode').setAttribute('aria-selected',String(m===mode));$(m+'-mode').tabIndex=m===mode?0:-1;}$('stats-workspace').setAttribute('aria-labelledby',mode+'-mode');render();}
for(const m of ['calculator','comparison'])$(m+'-mode').onclick=()=>changeMode(m);document.querySelector('.stats-mode-tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();changeMode(e.key==='Home'?'calculator':e.key==='End'?'comparison':mode==='calculator'?'comparison':'calculator');$(mode+'-mode').focus();}};$('battle-mode').onchange=output;
try{const response=await fetch(new URL('roster.json?v=stats-tool',root));if(!response.ok)throw Error('Could not load Tatari data.');data=await response.json();render();}catch(error){$('tool-status').textContent=error.message;$('tool-status').setAttribute('role','alert');}
